let arcAspect=1;
function arcCirc(ctx,x,y,r,fill,stroke,width=2){ctx.save();ctx.translate(x,y);ctx.scale(1,1/arcAspect);circ(ctx,0,0,r,fill,stroke,width);ctx.restore();}
function arcTxt(ctx,t,x,y,size=16,col=INK,align='center'){ctx.save();ctx.translate(x,y);ctx.scale(1,1/arcAspect);let physicalScale=Math.hypot(ctx.getTransform().a,ctx.getTransform().b)/(window.devicePixelRatio||1);txt(ctx,t,0,0,Math.max(size*Math.min(1,arcAspect),14/physicalScale),col,align);ctx.restore();}
function fieldFrame(i){let a=S.n===1?{x:12,y:20,w:576,h:560}:S.n===2?{x:18,y:i===0?311:34,w:564,h:255}:{x:12+(i%2)*294,y:i<2?311:34,w:282,h:255};let top=Math.max(32,18/(H/600)+6),bar=top-6,k=Math.min((a.w-16)/480,(a.h-top-8)/360);return{...a,k,bar,kx:(a.w-16)/480,ky:(a.h-top-8)/360,ox:a.x+8,oy:a.y+top};}
function fieldPoint(i,p){let f=fieldFrame(i);return p?{x:clamp((p.x-f.ox)/f.kx,0,480),y:clamp((p.y-f.oy)/f.ky,0,360)}:{x:240,y:300};}
function award(i,v,x=240,y=170){score(i,v);arcadeFX.push({state:S,i,v,x,y,t:0});window.StudioAudio?.effect(v>0?'success':'miss');}
function ball(x,y,r=9,color='#fffaf0'){arcCirc(c,x+2,y+3,r,'#17283224');arcCirc(c,x,y,r,color,'#263744',2);arcCirc(c,x-r*.25,y-r*.3,r*.23,'#ffffffbb');}
const arcadeImages={};for(let name of ['runner','rocket','boat','cannon','stone','keeper']){let im=new Image();im.src='assets/arcade/'+name+'.png';arcadeImages[name]=im;}
function asset(key,x,y,w,h){let im=arcadeImages[key];if(!im?.complete||!im.naturalWidth)return false;let k=Math.min(w/im.naturalWidth,h*arcAspect/im.naturalHeight);c.drawImage(im,x+(w-im.naturalWidth*k)/2,y+(h-im.naturalHeight*k/arcAspect)/2,im.naturalWidth*k,im.naturalHeight*k/arcAspect);return true;}
