function arcadeRegister(id,impl){engines[id]={init(){S.botForm=prefs.consistency==='variable'?chosen([.8,.9,1.1,1.2]):1;S.d={slots:Array.from({length:S.n},(_,i)=>impl.init(i)),botWait:Array(S.n).fill(0)};arcadeFX.length=0;},tap(i,p){if(!active())return;impl.down?.(S.d.slots[i],i,fieldPoint(i,p));},move(i,p){if(active())impl.move?.(S.d.slots[i],i,fieldPoint(i,p));},up(i,p){if(active())impl.up?.(S.d.slots[i],i,fieldPoint(i,p));},update(dt){for(let i=0;i<S.n;i++){let q=S.d.slots[i];if(i>=prefs.humans){S.d.botWait[i]-=dt;if(S.d.botWait[i]<=0){impl.bot?.(q,i);S.d.botWait[i]=(prefs.difficulty==='hard'?.07:prefs.difficulty==='easy'?.32:.16)/S.botForm;}}impl.step(q,i,dt);}for(let f of arcadeFX)f.t+=dt;while(arcadeFX.length&&arcadeFX[0].t>1)arcadeFX.shift();},draw(){c.save();c.scale(W/600,H/600);c.fillStyle='#ece8dc';c.fillRect(0,0,600,600);for(let i=0;i<S.n;i++){let f=fieldFrame(i);rr(c,f.x,f.y,f.w,f.h,12,'#fffcf4','#bdb6a8');rr(c,f.x+1,f.y+1,f.w-2,f.bar,10,['#315be8','#be402e','#217453','#7b50b0'][i]);arcAspect=H/W;arcTxt(c,pname(i)+'  /  '+S.g.action,f.x+f.w/2,f.y+1+f.bar/2,S.n>2?18:20,'#fff');c.save();c.translate(f.ox,f.oy);c.scale(f.kx,f.ky);arcAspect=(H/W)*f.ky/f.kx;c.beginPath();c.rect(0,0,480,360);c.clip();impl.draw(S.d.slots[i],i);arcadeFX.filter(v=>v.state===S&&v.i===i&&v.t<.9).forEach(v=>{c.globalAlpha=1-v.t;arcTxt(c,(v.v>0?'+':'')+v.v,v.x,v.y-v.t*42,36,v.v>0?'#21583c':'#a32e28');});c.restore();}c.restore();}};}
