 draw(q,i){skyline(!!mi());floor(310,'#536675');for(let x=-q.dist%60;x<480;x+=60){rr(c,x,323,45,8,2,'#748592');}for(let o of q.obs){if(o.gap){rr(c,o.x,308,o.w,52,0,'#202c41');line(c,o.x,310,o.x,359,'#f1cc78',3);line(c,o.x+o.w,310,o.x+o.w,359,'#f1cc78',3);}else{rr(c,o.x,256,o.w,54,3,'#bd7862','#674b45');rr(c,o.x-5,250,o.w+10,10,2,'#e5b08a');line(c,o.x,278,o.x+o.w,278,'#e0a68c',2);}}c.save();if(q.inv>0)c.globalAlpha=.35+Math.sin(S.elapsed*28)*.25;let bob=q.y>=285?Math.sin(q.dist*.12)*2:0;asset('runner',50,q.y+24-79/arcAspect+bob,56,79/arcAspect);c.restore();}
