 draw(q,i){c.fillStyle=mi()?'#253343':'#e8ece8';c.fillRect(0,0,480,360);texture('paper',.2);decorate('wobble',.09);rr(c,9,9,462,342,14,null,'#75898c');for(let b of q.rack)if(b.live){let colors=['#eaa06c','#f1c65b','#76baa5','#779fc9'];rr(c,b.x,b.y,64,18,4,colors[Math.floor((b.y-36)/24)],'#31475544');line(c,b.x+5,b.y+4,b.x+57,b.y+4,'#ffffff77',2);}rr(c,q.p-49,316,98,13,6,COL[i],'#263c4c');line(c,q.p-39,319,q.p+39,319,'#ffffff88',2);ball(q.b.x,q.b.y);if(q.ready)arcTxt(c,'TAP TO SERVE',240,221,24,mi()?'#fff4d7':'#3d5559');}
